/*
 Настройки бота управления умным домом.

 Заполнить вручную (искать «Заполнить»):
   bots.home.key          — токен бота из @BotFather
   access.profiles[].chatId — id семейного чата и личных сообщений
   access.users           — user_id тех, кому можно; узнать своё: команда /who

 Список устройств заполнять НЕ нужно: он строится обходом хаба.
 Что считать действием и кому что можно — actions.js и access.js.
*/
/* Собрано из src/02-settings/ — правки в этом файле потеряются при следующей сборке (tools/scenarios.py build). */
var TGActionsSettings = (function () {
// ───────────────────────────  actions.js  ───────────────────────────
function TGActionsActions() {

    var ACTIONS = {
        On: { kind: 'switch' },
        Active: { kind: 'switch', on: 1, off: 0, critical: true },
        Brightness: { kind: 'range', unit: '%', steps: [0, 25, 50, 75, 100] },
        ColorTemperature: { kind: 'range', points: 4 },
        TargetTemperature: { kind: 'range', unit: '°C', points: 5 },
        RotationSpeed: { kind: 'range', unit: '%', steps: [0, 20, 40, 60, 80, 100] },
        C_FanSpeed: { kind: 'range', points: 6 },
        TargetHeatingCoolingState: {
            kind: 'choice',
            labels: { '0': 'Выкл', '1': 'Тепло', '2': 'Холод', '3': 'Авто' }
        },
        SecuritySystemTargetState: {
            kind: 'choice',
            labels: { '0': 'Дома', '1': 'Ночь', '2': 'Охрана', '3': 'Снято' },
            critical: true
        }
    };

    var READONLY = {
        CurrentTemperature: { unit: '°C' },
        CurrentRelativeHumidity: { unit: '%' },
        BatteryLevel: { unit: '%' },
        ContactSensorState: { labels: { '0': 'закрыто', '1': 'открыто' } },
        LeakDetected: { labels: { '0': 'сухо', '1': 'ПРОТЕЧКА' } },
        SmokeDetected: { labels: { '0': 'чисто', '1': 'ДЫМ' } },
        MotionDetected: { labels: { 'false': 'нет движения', 'true': 'движение' } }
    };

    var OVERRIDES = {
        '22,34': { hide: true },                        // «Самоочистка» кондиционера
        '19,19': { title: 'Сирена', critical: true },   // Датчик дыма → сирена
        '9,15': { title: 'Кран воды', critical: true },
        '25,15': { title: 'Водопроводный кран', critical: true }
    };

    return {
        ACTIONS: ACTIONS,
        READONLY: READONLY,
        OVERRIDES: OVERRIDES
    };
}

// ───────────────────────────  visibility.js  ───────────────────────────
function TGActionsVisibility() {

    var hiddenRooms = [
        'Новая комната'
    ];

    var hiddenAccessories = [
    ];

    function contains(list, name) {
        for (var i = 0; i < list.length; i++) {
            if (list[i] === name) {
                return true;
            }
        }
        return false;
    }

    function isRoomHidden(name) {
        return contains(hiddenRooms, name);
    }

    function isAccessoryHidden(name) {
        return contains(hiddenAccessories, name);
    }

    function sortNames(names) {
        return names.slice().sort(function (a, b) {
            if (a === b) {
                return 0;
            }
            return a < b ? -1 : 1;
        });
    }

    return {
        hiddenRooms: hiddenRooms,
        hiddenAccessories: hiddenAccessories,
        isRoomHidden: isRoomHidden,
        isAccessoryHidden: isAccessoryHidden,
        sortNames: sortNames
    };
}

// ───────────────────────────  access.js  ───────────────────────────
function TGActionsAccess(ns) {
    var local = ns && ns.local ? ns.local : null;

    var profiles = [
        {
            key: 'f',
            title: 'Семейный чат',
            chatId: 'Заполнить',
            rooms: ['Гостиная', 'Кухня', 'Детские комнаты', 'Кабинет', 'Улица'],
            allowCritical: false
        },
        {
            key: 'p',
            title: 'Личные сообщения',
            chatId: 'Заполнить',
            rooms: ['*'],
            allowCritical: true
        }
    ];

    var users = {
        'Заполнить': { name: 'Хозяин', critical: true }
    };

    var strangerPolicy = 'deny';

    if (local) {
        if (local.chats) {
            for (var i = 0; i < profiles.length; i++) {
                if (local.chats[profiles[i].key]) {
                    profiles[i].chatId = local.chats[profiles[i].key];
                }
            }
        }
        if (local.users) {
            users = local.users;
        }
    }

    function profileByChat(chatId) {
        var id = String(chatId);
        for (var i = 0; i < profiles.length; i++) {
            if (String(profiles[i].chatId) === id) {
                return profiles[i];
            }
        }
        return null;
    }

    function roomAllowed(profile, roomName) {
        if (!profile) {
            return false;
        }
        for (var i = 0; i < profile.rooms.length; i++) {
            if (profile.rooms[i] === '*' || profile.rooms[i] === roomName) {
                return true;
            }
        }
        return false;
    }

    function check(chatId, userId, item) {
        var profile = profileByChat(chatId);
        if (!profile) {
            return { ok: false, reason: 'Этот чат не настроен для управления домом' };
        }
        var user = users[String(userId)];
        if (!user) {
            return {
                ok: false,
                silent: strangerPolicy === 'ignore',
                reason: 'Вас нет в списке разрешённых. Ваш id: ' + userId
            };
        }
        if (!roomAllowed(profile, item.room)) {
            return { ok: false, reason: 'Комната «' + item.room + '» недоступна в этом чате' };
        }
        if (item.critical && !(profile.allowCritical && user.critical)) {
            return { ok: false, reason: 'Действие «' + item.title + '» здесь запрещено' };
        }
        return { ok: true, user: user, profile: profile };
    }

    return {
        profiles: profiles,
        users: users,
        profileByChat: profileByChat,
        roomAllowed: roomAllowed,
        check: check
    };
}

// ───────────────────────────  discovery.js  ───────────────────────────
function TGActionsDiscovery(ns) {
    var rules = ns.actions;
    var hidden = ns.visibility;

    function addressOf(characteristic) {
        var uuid;
        try {
            uuid = String(characteristic.getUUID());
        } catch (e) {
            return null;
        }
        var parts = uuid.split('.');
        if (parts.length < 3) {
            return null;
        }
        var aId = parseInt(parts[0], 10);
        var cId = parseInt(parts[2], 10);
        if (isNaN(aId) || isNaN(cId)) {
            return null;
        }
        return { aId: aId, cId: cId, key: aId + ',' + cId };
    }

    function rangeSteps(rule, characteristic) {
        if (rule.steps) {
            return rule.steps;
        }
        var min = characteristic.getMinValue();
        var max = characteristic.getMaxValue();
        if (min === null || max === null || min === undefined || max === undefined || max <= min) {
            return null;
        }
        var count = rule.points || 5;
        var out = [];
        var step = (max - min) / (count - 1);
        for (var i = 0; i < count; i++) {
            out.push(Math.round(min + step * i));
        }
        return out;
    }

    function describe(characteristic, accessory, service, roomName) {
        var type = String(characteristic.getType());
        var addr = addressOf(characteristic);
        if (!addr) {
            return null;
        }

        var override = rules.OVERRIDES[addr.key] || {};
        if (override.hide) {
            return null;
        }

        var title = override.title
            || String(service.getName() || accessory.getName() || type);

        var base = {
            key: addr.key,
            aId: addr.aId,
            cId: addr.cId,
            room: roomName,
            device: String(accessory.getName()),
            title: title,
            type: type
        };

        var rule = rules.ACTIONS[type];
        if (rule) {
            base.kind = rule.kind;
            base.critical = override.critical !== undefined ? override.critical : !!rule.critical;
            base.on = rule.on !== undefined ? rule.on : true;
            base.off = rule.off !== undefined ? rule.off : false;
            base.unit = rule.unit || '';
            base.labels = rule.labels || null;
            if (rule.kind === 'range') {
                base.steps = rangeSteps(rule, characteristic);
                if (!base.steps) {
                    return null;
                }
            }
            return base;
        }

        var ro = rules.READONLY[type];
        if (ro) {
            base.kind = 'readonly';
            base.unit = ro.unit || '';
            base.labels = ro.labels || null;
            return base;
        }

        return null;
    }

    function scan() {
        var actions = [];
        var sensors = [];
        var roomNames = [];
        var errors = [];

        var rooms;
        try {
            rooms = Hub.getRooms();
        } catch (e) {
            return { actions: [], sensors: [], rooms: [], errors: ['getRooms: ' + e] };
        }

        for (var r = 0; r < rooms.length; r++) {
            var roomName;
            try {
                roomName = String(rooms[r].getName());
            } catch (e) {
                errors.push('room ' + r + ': ' + e);
                continue;
            }
            if (hidden.isRoomHidden(roomName)) {
                continue;
            }
            var accs;
            try {
                accs = rooms[r].getAccessories();
            } catch (e) {
                errors.push(roomName + ': ' + e);
                continue;
            }
            var roomHasSomething = false;

            for (var a = 0; a < accs.length; a++) {
                if (hidden.isAccessoryHidden(String(accs[a].getName()))) {
                    continue;
                }
                var services;
                try {
                    services = accs[a].getServices(true);
                } catch (e) {
                    errors.push(roomName + '/' + a + ': ' + e);
                    continue;
                }
                for (var s = 0; s < services.length; s++) {
                    var chars;
                    try {
                        chars = services[s].getCharacteristics();
                    } catch (e) {
                        continue;
                    }
                    for (var c = 0; c < chars.length; c++) {
                        var item;
                        try {
                            item = describe(chars[c], accs[a], services[s], roomName);
                        } catch (e) {
                            continue;
                        }
                        if (!item) {
                            continue;
                        }
                        roomHasSomething = true;
                        if (item.kind === 'readonly') {
                            sensors.push(item);
                        } else {
                            actions.push(item);
                        }
                    }
                }
            }

            if (roomHasSomething) {
                roomNames.push(roomName);
            }
        }

        return {
            actions: actions,
            sensors: sensors,
            rooms: hidden.sortNames(roomNames),
            errors: errors
        };
    }

    function readValue(item) {
        try {
            return Hub.getCharacteristicValue(item.aId, item.cId);
        } catch (e) {
            return null;
        }
    }

    function writeValue(item, value) {
        Hub.setCharacteristicValue(item.aId, item.cId, value);
    }

    return {
        scan: scan,
        readValue: readValue,
        writeValue: writeValue,
        addressOf: addressOf
    };
}

// ───────────────────────────  menu.js  ───────────────────────────
function TGActionsMenu(ns) {
    var access = ns.access;
    var discovery = ns.discovery;
    var sortNames = ns.visibility.sortNames;

    var BACK = '‹ Назад';

    function hashName(name) {
        var h = 5381;
        for (var i = 0; i < name.length; i++) {
            h = ((h * 33) ^ name.charCodeAt(i)) >>> 0;
        }
        return h.toString(36);
    }

    function homeSet(profile) {
        return profile.key + 'h';
    }

    function roomSet(profile, roomName) {
        return profile.key + 'r' + hashName(roomName);
    }

    function deviceSet(profile, item) {
        return profile.key + 'd' + item.aId;
    }

    function actionSet(profile, item) {
        return profile.key + 'a' + item.aId + '_' + item.cId;
    }

    function send(cq, text) {
        global.TGActions.sendSimpleMessage(cq.botName, String(cq.message.chat.id), text);
    }

    function open(cq, setName, text) {
        global.TGActions.sendInteractiveMessage(
            cq.botName, String(cq.message.chat.id), setName, text, { notify: false });
    }

    function valueLabel(item, value) {
        if (item.labels) {
            var byLabel = item.labels[String(value)];
            if (byLabel) {
                return byLabel;
            }
        }
        if (item.kind === 'switch') {
            return value === item.on ? 'включено' : 'выключено';
        }
        if (value === null || value === undefined) {
            return '—';
        }
        return String(value) + (item.unit ? ' ' + item.unit : '');
    }

    function actionButtons(item, backSet) {
        var row = [];
        var i;

        if (item.kind === 'switch') {
            row.push(valueButton(item, item.on, 'Включить'));
            row.push(valueButton(item, item.off, 'Выключить'));
        } else if (item.kind === 'range') {
            for (i = 0; i < item.steps.length; i++) {
                row.push(valueButton(item, item.steps[i],
                    String(item.steps[i]) + (item.unit ? ' ' + item.unit : '')));
            }
        } else if (item.kind === 'choice') {
            for (var k in item.labels) {
                if (item.labels.hasOwnProperty(k)) {
                    row.push(valueButton(item, parseInt(k, 10), item.labels[k]));
                }
            }
        }

        var rows = [];
        for (i = 0; i < row.length; i += 3) {
            rows.push(row.slice(i, i + 3));
        }
        rows.push([navButton(backSet, BACK)]);
        return rows;
    }

    function valueButton(item, value, label) {
        return {
            text: label,
            handler: function (cq) {
                var verdict = access.check(cq.message.chat.id, cq.userId, item);
                if (!verdict.ok) {
                    if (!verdict.silent) {
                        send(cq, '⛔ ' + verdict.reason);
                    }
                    return;
                }
                try {
                    discovery.writeValue(item, value);
                } catch (e) {
                    send(cq, '⚠️ Не удалось: ' + e);
                    return;
                }
                send(cq, '✅ ' + item.room + ' · ' + item.title + ' → ' + label);
            }
        };
    }

    function navButton(setName, label) {
        return {
            text: label,
            handler: function (cq) {
                open(cq, setName, label === BACK ? 'Назад' : label);
            }
        };
    }

    function build(inventory) {
        var buttonSets = {};
        var homeOf = {};
        var index = { rooms: 0, devices: 0, actions: 0 };

        for (var p = 0; p < access.profiles.length; p++) {
            var profile = access.profiles[p];
            var homeRows = [];

            for (var r = 0; r < inventory.rooms.length; r++) {
                var roomName = inventory.rooms[r];
                if (!access.roomAllowed(profile, roomName)) {
                    continue;
                }

                var devices = groupByDevice(inventory.actions, roomName, profile);
                if (!devices.order.length) {
                    continue;
                }

                var rSet = roomSet(profile, roomName);
                var deviceRows = [];

                for (var d = 0; d < devices.order.length; d++) {
                    var deviceName = devices.order[d];
                    var items = devices.map[deviceName];
                    index.devices++;

                    if (items.length === 1) {
                        var only = actionSet(profile, items[0]);
                        buttonSets[only] = actionButtons(items[0], rSet);
                        deviceRows.push([navButton(only, deviceName)]);
                        index.actions++;
                        continue;
                    }

                    var dSet = deviceSet(profile, items[0]);
                    var actionRows = [];

                    for (var i = 0; i < items.length; i++) {
                        var aSet = actionSet(profile, items[i]);
                        buttonSets[aSet] = actionButtons(items[i], dSet);
                        actionRows.push([navButton(aSet, items[i].title)]);
                        index.actions++;
                    }
                    actionRows.push([navButton(rSet, BACK)]);
                    buttonSets[dSet] = actionRows;
                    deviceRows.push([navButton(dSet, deviceName)]);
                }

                deviceRows.push([navButton(homeSet(profile), BACK)]);
                buttonSets[rSet] = deviceRows;
                homeRows.push([navButton(rSet, roomName)]);
                index.rooms++;
            }

            buttonSets[homeSet(profile)] = homeRows.length
                ? homeRows
                : [[{ text: 'Нет доступных устройств', handler: function () {} }]];
            homeOf[String(profile.chatId)] = homeSet(profile);
        }

        return { buttonSets: buttonSets, homeOf: homeOf, index: index };
    }

    function groupByDevice(actions, roomName, profile) {
        var map = {};
        var order = [];
        for (var i = 0; i < actions.length; i++) {
            var item = actions[i];
            if (item.room !== roomName) {
                continue;
            }
            if (item.critical && !profile.allowCritical) {
                continue;
            }
            if (!map[item.device]) {
                map[item.device] = [];
                order.push(item.device);
            }
            map[item.device].push(item);
        }

        for (var name in map) {
            if (map.hasOwnProperty(name)) {
                map[name].sort(byTitle);
            }
        }
        return { map: map, order: sortNames(order) };
    }

    function byTitle(a, b) {
        if (a.title === b.title) {
            return 0;
        }
        return a.title < b.title ? -1 : 1;
    }

    return {
        build: build,
        valueLabel: valueLabel
    };
}

// ───────────────────────────  commands.js  ───────────────────────────
function TGActionsCommands(ns) {
    var access = ns.access;
    var discovery = ns.discovery;
    var menu = ns.menu;
    var state = ns.menuState;

    function reply(ctx, text) {
        global.TGActions.sendSimpleMessage(ctx.botName, String(ctx.chatId), text);
    }

    function byTitle(a, b) {
        if (a.title === b.title) {
            return 0;
        }
        return a.title < b.title ? -1 : 1;
    }

    function gate(ctx) {
        var profile = access.profileByChat(ctx.chatId);
        if (!profile) {
            reply(ctx, '⛔ Этот чат не настроен для управления домом.\nchat_id: ' + ctx.chatId);
            return null;
        }
        if (!access.users[String(ctx.userId)]) {
            reply(ctx, '⛔ Вас нет в списке разрешённых.\nВаш id: ' + ctx.userId);
            return null;
        }
        return profile;
    }

    var commands = {
        home: {
            description: 'Меню управления домом',
            handler: function (ctx) {
                var profile = gate(ctx);
                if (!profile) {
                    return;
                }
                global.TGActions.sendInteractiveMessage(
                    ctx.botName, String(ctx.chatId), profile.key + 'h',
                    'Дом. Выберите комнату:', { notify: false });
            }
        },

        status: {
            description: 'Показания датчиков',
            handler: function (ctx) {
                var profile = gate(ctx);
                if (!profile) {
                    return;
                }
                var byRoom = {};
                var sensors = state.inventory.sensors;
                var i;
                for (i = 0; i < sensors.length; i++) {
                    var s = sensors[i];
                    if (!byRoom[s.room]) {
                        byRoom[s.room] = [];
                    }
                    byRoom[s.room].push(s);
                }

                var lines = [];
                var rooms = state.inventory.rooms;
                for (i = 0; i < rooms.length; i++) {
                    var room = rooms[i];
                    if (!access.roomAllowed(profile, room) || !byRoom[room]) {
                        continue;
                    }
                    var list = byRoom[room].slice().sort(byTitle);
                    lines.push('');
                    lines.push('*' + room + '*');
                    for (var j = 0; j < list.length; j++) {
                        lines.push(list[j].title + ': '
                            + menu.valueLabel(list[j], discovery.readValue(list[j])));
                    }
                }
                reply(ctx, lines.length ? lines.join('\n') : 'Датчиков в доступных комнатах нет');
            }
        },

        who: {
            description: 'Кто я для бота',
            anyChat: true,
            handler: function (ctx) {
                var profile = access.profileByChat(ctx.chatId);
                var user = access.users[String(ctx.userId)];
                reply(ctx, [
                    'Ваш user_id: ' + ctx.userId,
                    'Имя: ' + (ctx.userName || '—'),
                    'chat_id: ' + ctx.chatId,
                    'Профиль чата: ' + (profile ? profile.title : 'не настроен'),
                    'В белом списке: ' + (user ? 'да' : 'нет'),
                    'Критичные действия: ' + (user && user.critical && profile && profile.allowCritical
                        ? 'разрешены' : 'запрещены')
                ].join('\n'));
            }
        },

        refresh: {
            description: 'Перечитать устройства из хаба',
            handler: function (ctx) {
                if (!gate(ctx)) {
                    return;
                }
                var result = state.refresh();
                reply(ctx, [
                    'Обход хаба выполнен.',
                    'Комнат: ' + result.inventory.rooms.length,
                    'Действий: ' + result.index.actions,
                    'Датчиков: ' + result.inventory.sensors.length,
                    result.inventory.errors.length
                        ? 'Ошибок обхода: ' + result.inventory.errors.length
                        : 'Ошибок нет'
                ].join('\n'));
            }
        },

        help: {
            description: 'Список команд',
            handler: function (ctx) {
                var lines = [];
                for (var name in commands) {
                    if (commands.hasOwnProperty(name)) {
                        lines.push('/' + name + ' — ' + commands[name].description);
                    }
                }
                reply(ctx, lines.join('\n'));
            }
        }
    };

    return commands;
}

// ───────────────────────────  index.js  ───────────────────────────
function TGActionsSettingsIndex() {
    var ns = {};

    ns.local = (typeof TGActionsLocal === 'function') ? TGActionsLocal() : null;

    ns.actions = TGActionsActions();
    ns.visibility = TGActionsVisibility();
    ns.access = TGActionsAccess(ns);
    ns.discovery = TGActionsDiscovery(ns);
    ns.menu = TGActionsMenu(ns);

    var buttonSets = {};

    ns.menuState = {
        inventory: { actions: [], sensors: [], rooms: [], errors: [] },
        index: { rooms: 0, devices: 0, actions: 0 },
        refresh: function () {
            var inventory = ns.discovery.scan();
            var built = ns.menu.build(inventory);

            for (var old in buttonSets) {
                if (buttonSets.hasOwnProperty(old)) {
                    delete buttonSets[old];
                }
            }
            for (var name in built.buttonSets) {
                if (built.buttonSets.hasOwnProperty(name)) {
                    buttonSets[name] = built.buttonSets[name];
                }
            }

            ns.menuState.inventory = inventory;
            ns.menuState.index = built.index;
            return { inventory: inventory, index: built.index };
        }
    };

    ns.menuState.refresh();

    var chats = { _default: ns.access.profiles[0].key };
    for (var i = 0; i < ns.access.profiles.length; i++) {
        chats[ns.access.profiles[i].key] = ns.access.profiles[i].chatId;
    }

    return {
        botDescription: 'Управление умным домом на базе Sprut.hub',
        botShortDescription: 'Умный дом',
        bots: {
            _default: 'home',
            home: {
                key: ns.local && ns.local.botKey ? ns.local.botKey : 'Заполнить',
                description: 'Управление умным домом',
                shortDescription: 'Умный дом',
                autoStart: true
            }
        },
        chats: chats,
        replyKeyboardSets: {},
        buttonSets: buttonSets,
        botCommands: TGActionsCommands(ns),
        _diag: ns.menuState
    };
}

return TGActionsSettingsIndex();
})();
